using System;using System.Collections.Generic;using Exoduser.UnityPort;
class Program {
 static int count;static void Check(bool ok,string text){count++;if(!ok)throw new Exception(text);}
 static bool Near(float a,float b){return Math.Abs(a-b)<.015f;}
 static bool In(float x,float y,float w,float h,float bx,float by,float bw,float bh){return x>=bx-.01f&&y>=by-.01f&&x+w<=bx+bw+.01f&&y+h<=by+bh+.01f;}
 static void PixelTests(){var pieces=NativeStageClearMaterialLayout.Plan(560,546,new NativeStageClearPresentation.Area(28,462,504,56));foreach(float scale in new[]{1f,508f/578}){float tx=(1600-560*scale)/2,ty=30.055363f;foreach(var p in pieces){if(!p.Name.StartsWith("모서리"))continue;var q=NativeStageClearMaterialLayout.PixelAligned(p,tx,ty,scale);Check(Near(q.X,(float)Math.Round(q.X))&&Near(q.Y,(float)Math.Round(q.Y))&&Near(q.W,(float)Math.Round(q.W))&&Near(q.H,(float)Math.Round(q.H)),"실패: 2px행 소수배율은 정수화면영역과 UV역보정이 필요");Check(q.W>0&&q.H>0&&Math.Abs(q.Y-(ty+p.Y*scale))<=.501f&&Math.Abs(q.Y+q.H-(ty+(p.Y+p.H)*scale))<=.501f,"공유 픽셀경계의 반올림오차 한계");int pi=pieces.IndexOf(p);if(pi>0){var prev=pieces[pi-1];if(prev.Name==p.Name&&Near(prev.Y+prev.H,p.Y)){var z=NativeStageClearMaterialLayout.PixelAligned(prev,tx,ty,scale);Check(Near(z.Y+z.H,q.Y),"인접행의 빈띠/겹침알파띠 금지");}}float cx=q.X+q.W/2,cy=q.Y+q.H/2;Check(Near(q.Sx+(cx-q.X)*q.Sw/q.W,p.Sx+(cx-tx-p.X*scale)*p.Sw/(p.W*scale)),"픽셀스냅 뒤 같은 수평 원화위치");Check(Near(q.Sy+(cy-q.Y)*q.Sh/q.H,p.Sy+(cy-ty-p.Y*scale)*p.Sh/(p.H*scale)),"픽셀스냅 뒤 같은 수직 원화위치");Check(Near(q.W/q.Sw,q.H/q.Sh),"소수배율 역보정 뒤 재질 동일배율");}}}
 static void Main(string[] args){Console.OutputEncoding=new System.Text.UTF8Encoding(false);try {if(args.Length>0&&args[0]=="pixels"){PixelTests();Console.WriteLine("통과 "+count+" / 소수배율 픽셀·UV연속성 검사");return;}
 var model=NativeStageClearPresentation.Build(new NativeStageClearPresentation.Summary{Kills=137,Total=168,Seconds=88,SpAwarded=10,Regions=4,Potions=0,Deaths=0});
 foreach(var screen in new[]{(1600f,900f),(960f,540f),(640f,360f)}){var l=NativeStageClearPresentation.Arrange(screen.Item1,screen.Item2,model);var b=new NativeStageClearPresentation.Area((l.Next.X-l.Panel.X)/l.Scale,(l.Next.Y-l.Panel.Y)/l.Scale,l.Next.Width/l.Scale,l.Next.Height/l.Scale);var patches=NativeStageClearMaterialLayout.Plan(560,l.LogicalHeight,b);Check(patches.Count>12,"실패: 평면색 대신 원화 UV 재질·프레임 실물이 필요");int body=0,button=0;foreach(var p in patches){Check(p.Sw>0&&p.Sh>0&&p.W>0&&p.H>0,"유효한 UV/표시 크기");Check(In(p.Sx,p.Sy,p.Sw,p.Sh,0,0,p.Iron?480:980,p.Iron?480:1056),"원화 밖 UV 금지");Check(Near(p.W/p.Sw,p.H/p.Sh),"방향별 재질/모서리 늘어짐 금지");if(p.Iron){if(p.Button)button++;else body++;}else{bool corner=(p.Sx+p.Sw<=56.01f||p.Sx>=923.99f)&&(p.Sy+p.Sh<=56.01f||p.Sy>=999.99f);bool rail=p.Sy>=8.99f&&p.Sy+p.Sh<=19.01f||p.Sy>=1031.99f&&p.Sy+p.Sh<=1042.01f||p.Sx>=5.99f&&p.Sx+p.Sw<=15.01f||p.Sx>=964.99f&&p.Sx+p.Sw<=975.01f;bool blankFrame=p.Button&&(p.Sx>=263&&p.Sx+p.Sw<=950)&&(p.Sy>=372&&p.Sy+p.Sh<=951)&&(p.Sx+p.Sw<=273.01f||p.Sx>=939.99f||p.Sy+p.Sh<=382.01f||p.Sy>=940.99f);Check(corner||rail||blankFrame,"기사·문양·기능칸 내용 UV 금지");}var d=l.ToScreen(p.X,p.Y,p.W,p.H);Check(In(d.X,d.Y,d.Width,d.Height,16,16,screen.Item1-32,screen.Item2-32),"원화 외곽 포함 화면여백16 유지");}Check(body==1&&button==1,"본문·버튼 iron 각각 한장, 반복타일0");Check(l.HitNext(l.Next.X+2,l.Next.Y+2)&&l.HitNext(l.Next.X+l.Next.Width-2,l.Next.Y+l.Next.Height-2),"새 프레임의 실제 버튼 표시/입력 동일");if(screen.Item1>=960)Check(l.Next.Height>=44,"작은창에서도 버튼높이44 이상");}
 Console.WriteLine("통과 "+count+" / 새 UV·재질·프레임 경계 검사");
 }catch(Exception e){Console.WriteLine(e.Message);Environment.ExitCode=1;}}}
